import csv, re
from collections import defaultdict, Counter
from urllib.parse import urlparse

def extract_repo_slug(removal_ref: str) -> str | None:
    if not removal_ref:
        return None
    # Take the first URL-like token
    tokens = re.split(r'\s+', removal_ref.strip())
    for t in tokens:
        if "github.com" in t:
            # Strip trailing punctuation
            t = t.strip('",')
            try:
                u = urlparse(t)
            except Exception:
                continue
            if "github.com" not in u.netloc:
                continue
            # Path like /owner/repo/...
            parts = [p for p in u.path.split('/') if p]
            if len(parts) >= 2:
                return f"{parts[0]}/{parts[1]}"
    return None

rows = []
with open("labeled_data.csv", newline="", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

by_repo = defaultdict(list)
for row in rows:
    repo = extract_repo_slug(row.get("removal-ref", ""))
    replaced = (row.get("replaced-by") or "").strip()
    by_repo[repo].append(replaced)

print(f"Total labeled rows: {len(rows)}")
print(f"Unique repos (including None): {len(by_repo)}")

# Show repos with multiple distinct replacement labels
conflicts = {}
for repo, reps in by_repo.items():
    uniq = sorted(set(r for r in reps if r))
    if len(uniq) > 1:
        conflicts[repo] = uniq

print("\nRepos with multiple distinct 'replaced-by' values:")
for repo, uniq in sorted(conflicts.items(), key=lambda x: (x[0] or "")):
    print(f"  {repo}: {uniq}")

# Now assign a single canonical replacement per repo.
def normalize_tool(raw: str) -> str | None:
    if not raw:
        return None
    s = raw.lower()
    if "cmake" in s and "make" in s:
        # Row with "CMake + MAKE (go build)" – Table 5 treats this as Make only
        return "Make"
    if "swift" in s and "pm" in s:
        return "SPM"
    if "mage" in s:
        return "Mage"
    if "setuptools" in s:
        return "Setuptools"
    if "gradle" in s:
        return "Gradle"
    if s.startswith("sbt"):
        return "SBT"
    if "nix" in s:
        return "Nix"
    if "google cloud build" in s:
        return "Google Cloud Build"
    if "cmake" in s:
        return "CMake"
    if "make" in s:
        return "Make"
    if "go build" in s:
        return "Go Build"
    return None

tool_by_repo = {}
for repo, reps in by_repo.items():
    norm_tools = {normalize_tool(r) for r in reps if normalize_tool(r)}
    if not norm_tools:
        continue
    # If multiple, just report; pick the first deterministically
    if len(norm_tools) > 1:
        print(f"\n[WARN] Repo {repo} has multiple normalized tools: {sorted(norm_tools)}")
    tool_by_repo[repo] = sorted(norm_tools)[0]

project_counts = Counter(tool_by_repo.values())
print("\nProject-level counts by replacement technology:")
for k, v in sorted(project_counts.items()):
    print(f"  {k}: {v}")
print(f"\nTOTAL projects counted: {sum(project_counts.values())}")
